import React, { useState, useEffect } from "react";
import API from "../utils/axiosInstance";
import { Container, Table, Button, Form, Modal, Spinner } from "react-bootstrap";

const AdminDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentEventId, setCurrentEventId] = useState(null);
  const [newEvent, setNewEvent] = useState({ title: "", description: "", date: "", location: "" });
  const [registrants, setRegistrants] = useState([]);
  const [showRegistrantsModal, setShowRegistrantsModal] = useState(false);

  // ✅ Fetch Events
  const fetchEvents = async () => {
    try {
      const response = await API.get("/events/admin-events");
      setEvents(response.data);
    } catch (error) {
      console.error("Error fetching events:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // ✅ Fetch Registrants
  const fetchRegistrants = async (eventId) => {
    try {
      const response = await API.get(`/events/${eventId}/registrants`);
      setRegistrants(Array.isArray(response.data) ? response.data : []);
      setShowRegistrantsModal(true);
    } catch (error) {
      console.error("Error fetching registrants:", error);
      setRegistrants([]);
    }
  };

  // ✅ Show Modal for Creating/Editing Events
  const handleShowModal = (event = null) => {
    if (event) {
      setEditMode(true);
      setCurrentEventId(event._id);
      setNewEvent({
        title: event.title,
        description: event.description,
        date: event.date.split("T")[0], // Fix date format
        location: event.location || "",
      });
    } else {
      setEditMode(false);
      setCurrentEventId(null);
      setNewEvent({ title: "", description: "", date: "", location: "" });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => setShowModal(false);

  // ✅ Handle Input Changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewEvent((prevEvent) => ({ ...prevEvent, [name]: value }));
  };

  // ✅ Create or Update Event
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!newEvent.title || !newEvent.description || !newEvent.date || !newEvent.location) {
      alert("Please fill in all required fields!");
      return;
    }

    try {
      const accessToken = localStorage.getItem("accessToken");
      const config = { headers: { Authorization: `Bearer ${accessToken}` } };
      const formData = {
        title: newEvent.title,
        description: newEvent.description,
        date: newEvent.date,
        location: newEvent.location,
      };

      let response;
      if (editMode) {
        response = await API.put(`/events/${currentEventId}`, formData, config);
      } else {
        response = await API.post("/events", formData, config);
      }

      if (response.status === 200 || response.status === 201) {
        fetchEvents(); // Refresh events
        setShowModal(false);
        setNewEvent({ title: "", description: "", date: "", location: "" });
      }
    } catch (error) {
      console.error("Error creating/updating event:", error);
    }
  };

  // ✅ Delete Event
  const handleDelete = async (eventId) => {
    try {
      await API.delete(`/events/${eventId}`);
      fetchEvents(); // Refresh events after deleting
    } catch (error) {
      console.error("Error deleting event:", error);
    }
  };

  return (
    <Container className="admin-dashboard-container mt-5">
      <h2 className="text-center mb-4">Admin Dashboard</h2>

      {/* ✅ Loading Spinner */}
      {loading ? (
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      ) : (
        <Table striped bordered hover>
          <thead>
            <tr>
              <th>Title</th>
              <th>Description</th>
              <th>Date</th>
              <th>Location</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {events.map((event) => (
              <tr key={event._id}>
                <td>{event.title}</td>
                <td>{event.description}</td>
                <td>{new Date(event.date).toLocaleDateString()}</td>
                <td>{event.location}</td>
                <td>
                  <Button
                    variant="info"
                    onClick={() => fetchRegistrants(event._id)}
                    className="me-2"
                  >
                    <i className="bi bi-eye"></i> View Registrants
                  </Button>
                  <Button
                    variant="warning"
                    onClick={() => handleShowModal(event)}
                    className="me-2"
                  >
                    Edit
                  </Button>
                  <Button variant="danger" onClick={() => handleDelete(event._id)}>
                    Delete
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}

      {/* ✅ Create New Event Button */}
      <Button variant="primary" onClick={() => handleShowModal()}>
        Create New Event
      </Button>

      {/* ✅ Registrants Modal */}
      <Modal show={showRegistrantsModal} onHide={() => setShowRegistrantsModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Registrants for the Event</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {registrants.length > 0 ? (
            <ul>
              {registrants.map((registrant) => (
                <li key={registrant._id}>
                  <strong>Name:</strong> {registrant.name}
                </li>
              ))}
            </ul>
          ) : (
            <p>No registrants for this event.</p>
          )}
        </Modal.Body>
      </Modal>

      {/* ✅ Create & Edit Events Modal */}
      <Modal show={showModal} onHide={handleCloseModal}>
        <Modal.Header closeButton>
          <Modal.Title>{editMode ? "Edit Event" : "Create New Event"}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleSubmit}>
            <Form.Group controlId="formTitle">
              <Form.Label>Title</Form.Label>
              <Form.Control
                type="text"
                name="title"
                value={newEvent.title}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formDescription" className="mt-3">
              <Form.Label>Description</Form.Label>
              <Form.Control
                type="text"
                name="description"
                value={newEvent.description}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formDate" className="mt-3">
              <Form.Label>Date</Form.Label>
              <Form.Control
                type="date"
                name="date"
                value={newEvent.date}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Form.Group controlId="formLocation" className="mt-3">
              <Form.Label>Location</Form.Label>
              <Form.Control
                type="text"
                name="location"
                value={newEvent.location}
                onChange={handleChange}
                required
              />
            </Form.Group>
            <Button variant="primary" type="submit" className="mt-4">
              {editMode ? "Update Event" : "Create Event"}
            </Button>
          </Form>
        </Modal.Body>
      </Modal>
    </Container>
  );
};

export default AdminDashboard;
